 setup();missing_outbound=true;assert(fails([&]{mission_netsock_host_worker(b,frame);}));assert(depth==0&&dispatches==2&&sleeps==0&&ends==0&&get(0x10019b08)==0);missing_outbound=false;
 setup();auto missing=b;missing.call={};assert(fails([&]{mission_netsock_host_worker(missing,frame);}));assert(get(frame)==0&&get(frame+4)==0xbbbbbbbb&&depth==0);
 setup();missing=b;missing.frame={};assert(fails([&]{mission_netsock_host_worker(missing,frame);}));assert(clocks==1&&depth==0&&get(0x10019b34)==100&&sleeps==0);
